# currency conversion anywhere in this module.
AMOUNT_EDGES = [0, 1_000, 5_000, 20_000, 100_000, np.inf]
AMOUNT_LABELS = ["<1,000", "1,000-4,999", "5,000-19,999", "20,000-99,999", ">=100,000"]
